sys_script_client.script:
function onSubmit() {

    var isEmergency = g_form.getValue('is_emergency_leave');

    // Emergency leave can have past dates
    if (isEmergency == 'true') {
        return true;
    }

    var startDate = g_form.getValue('start_date');

    if (!startDate) {
        return true;
    }

    var start = new Date(startDate);
    var today = new Date();

    // Compare dates only, ignoring time
    start.setHours(0, 0, 0, 0);
    today.setHours(0, 0, 0, 0);

    if (start < today) {

        g_form.addErrorMessage(
            'Start Date cannot be in the past unless the request is marked as Emergency.'
        );

        return false;
    }

    return true;
}
